function run(args){console.log('start');const safari=Application('Safari'),window=safari.windows[0];console.log('window object');if(window.id()!==1470||!window.currentTab.url().startsWith('http://127.0.0.1:4186/'))throw Error('Front window is not the owned VDoc QA document');console.log('identity verified');safari.activate();console.log('activated');const se=Application('System Events');for(const code of args){if(safari.windows[0].id()!==1470||!safari.windows[0].currentTab.url().startsWith('http://127.0.0.1:4186/'))throw Error('Focus changed; stopping');console.log('key guard passed '+code);if(code==='reload')se.keystroke('r',{using:['command down']});else if(code==='find')se.keystroke('f',{using:['command down']});else if(code==='undo')se.keystroke('z',{using:['command down']});else if(code==='redo')se.keystroke('z',{using:['command down','shift down']});else se.keyCode(Number(code));console.log('key delivered '+code);delay(.12)}return 'Physical key codes delivered only to owned QA window';}
